/* SALDO FINAL POR DIA (Oracle) */WITHDateSeries AS (  SELECT (TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15)) + LEVEL - 1) AS dia  FROM DUAL  CONNECT BY LEVEL <= (    TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_FIM_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) + 15))  - TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15)) + 1  )),sbc_base AS (  SELECT NVL(SUM(sbc.SALDOREAL), 0) AS saldo_base  FROM TGFSBC sbc  JOIN TSICTA cb ON cb.CODCTABCOINT = sbc.CODCTABCOINT  WHERE sbc.REFERENCIA = TO_DATE(TO_CHAR(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15), 'YYYY-MM') || '-01', 'YYYY-MM-DD')    AND cb.ATIVA  = 'S'    AND cb.CLASSE IN ('A','C')    AND (:VAR_EMPRESA_FC IS NULL OR :VAR_EMPRESA_FC = '' OR INSTR(',' || :VAR_EMPRESA_FC || ',', ',' || TO_CHAR(cb.CODEMP) || ',') > 0)    AND (:VAR_CONTA_BANCARIA_FC IS NULL OR :VAR_CONTA_BANCARIA_FC = '' OR INSTR(',' || :VAR_CONTA_BANCARIA_FC || ',', ',' || TO_CHAR(cb.CODCTABCOINT) || ',') > 0)),pre_mov AS (  SELECT NVL(SUM(mbc.VLRLANC * mbc.RECDESP), 0) AS pre_mov  FROM TGFMBC mbc  JOIN TSICTA cb ON cb.CODCTABCOINT = mbc.CODCTABCOINT  WHERE mbc.DTLANC >= TO_DATE(TO_CHAR(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15), 'YYYY-MM') || '-01', 'YYYY-MM-DD')    AND TRUNC(mbc.DTLANC) < TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15))    AND cb.ATIVA  = 'S'    AND cb.CLASSE IN ('A','C')    AND (:VAR_EMPRESA_FC IS NULL OR :VAR_EMPRESA_FC = '' OR INSTR(',' || :VAR_EMPRESA_FC || ',', ',' || TO_CHAR(cb.CODEMP) || ',') > 0)    AND (:VAR_CONTA_BANCARIA_FC IS NULL OR :VAR_CONTA_BANCARIA_FC = '' OR INSTR(',' || :VAR_CONTA_BANCARIA_FC || ',', ',' || TO_CHAR(cb.CODCTABCOINT) || ',') > 0)),MOV_RAW AS (  SELECT TRUNC(mbc.DTLANC) AS dia, SUM(mbc.VLRLANC * mbc.RECDESP) AS mov_dia  FROM TGFMBC mbc  JOIN TSICTA cb ON cb.CODCTABCOINT = mbc.CODCTABCOINT  WHERE TRUNC(mbc.DTLANC) < TRUNC(SYSDATE)    AND TRUNC(mbc.DTLANC) BETWEEN TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15)) AND TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_FIM_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) + 15))    AND cb.ATIVA  = 'S'    AND cb.CLASSE IN ('A','C')    AND (:VAR_EMPRESA_FC IS NULL OR :VAR_EMPRESA_FC = '' OR INSTR(',' || :VAR_EMPRESA_FC || ',', ',' || TO_CHAR(cb.CODEMP) || ',') > 0)    AND (:VAR_CONTA_BANCARIA_FC IS NULL OR :VAR_CONTA_BANCARIA_FC = '' OR INSTR(',' || :VAR_CONTA_BANCARIA_FC || ',', ',' || TO_CHAR(cb.CODCTABCOINT) || ',') > 0)  GROUP BY TRUNC(mbc.DTLANC)  UNION ALL  SELECT TRUNC(fin.DTVENC) AS dia, SUM(fin.VLRDESDOB) AS mov_dia  FROM TGFFIN fin  WHERE fin.RECDESP = 1 AND fin.DHBAIXA IS NULL AND fin.PROVISAO = 'N' AND TRUNC(fin.DTVENC) >= TRUNC(SYSDATE)    AND TRUNC(fin.DTVENC) BETWEEN TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15)) AND TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_FIM_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) + 15))    AND (:VAR_EMPRESA_FC IS NULL OR :VAR_EMPRESA_FC = '' OR INSTR(',' || :VAR_EMPRESA_FC || ',', ',' || TO_CHAR(fin.CODEMP) || ',') > 0)    AND (:VAR_CONTA_BANCARIA_FC IS NULL OR :VAR_CONTA_BANCARIA_FC = '' OR INSTR(',' || :VAR_CONTA_BANCARIA_FC || ',', ',' || TO_CHAR(fin.CODCTABCOINT) || ',') > 0)  GROUP BY TRUNC(fin.DTVENC)  UNION ALL  SELECT TRUNC(fin.DTVENC) AS dia, SUM(-fin.VLRDESDOB) AS mov_dia  FROM TGFFIN fin  WHERE fin.RECDESP = -1 AND fin.DHBAIXA IS NULL AND fin.PROVISAO = 'N' AND TRUNC(fin.DTVENC) >= TRUNC(SYSDATE)    AND TRUNC(fin.DTVENC) BETWEEN TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15)) AND TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_FIM_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) + 15))    AND (:VAR_EMPRESA_FC IS NULL OR :VAR_EMPRESA_FC = '' OR INSTR(',' || :VAR_EMPRESA_FC || ',', ',' || TO_CHAR(fin.CODEMP) || ',') > 0)    AND (:VAR_CONTA_BANCARIA_FC IS NULL OR :VAR_CONTA_BANCARIA_FC = '' OR INSTR(',' || :VAR_CONTA_BANCARIA_FC || ',', ',' || TO_CHAR(fin.CODCTABCOINT) || ',') > 0)  GROUP BY TRUNC(fin.DTVENC)),MOV_DIA AS (SELECT dia, SUM(mov_dia) AS mov_dia FROM MOV_RAW GROUP BY dia)SELECT TO_CHAR(d.dia, 'DD/MM/YYYY') AS DIA, sbc_base.saldo_base + pre_mov.pre_mov + NVL(SUM(NVL(m.mov_dia, 0)) OVER (ORDER BY d.dia ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), 0) AS SALDO_FINALFROM DateSeries d CROSS JOIN sbc_base CROSS JOIN pre_mov LEFT JOIN MOV_DIA m ON m.dia = d.diaWHERE d.dia BETWEEN TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_INICIO_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) - 15)) AND TRUNC(NVL(TO_DATE(SUBSTR(:VAR_DATA_FIM_FC, 1, 10), 'YYYY-MM-DD'), TRUNC(SYSDATE) + 15))ORDER BY d.dia